template <typename TSource>
__device__ static inline auto Average(TSource source) {
double sum = 0;
int count = 0;
while (source.MoveNext()) {
sum += (double)source.Current();
count++;
}
if (count == 0) {
__gsharp_trap(GSharpErrorCode::InvalidOperation, ""Sequence contains no elements"");
